<script setup>
import { onMounted, ref } from "vue";
import { api } from "../api";
const catalog = ref([]), loading = ref(true), error = ref(""), selected = ref(null), artifactLoading = ref(false);
onMounted(async () => { try { const data = await api("/evaluation/catalog"); catalog.value = data.artifacts; } catch (e) { error.value = e.message; } finally { loading.value = false; } });
async function openArtifact(item) { artifactLoading.value = true; try { selected.value = await api(`/evaluation/artifacts/${item.artifact.split("/").map(encodeURIComponent).join("/")}`); } catch (e) { error.value = e.message; } finally { artifactLoading.value = false; } }
const groupLabel = (name) => name.includes("oos") || name.includes("holdout") ? "样本外 / 回归集" : name.includes("route") ? "Agent 路由评估" : name.includes("retrieval") ? "检索评估" : "开发集 / 结果档案";
</script>
<template><div class="page-stack"><section class="welcome-row"><div><div class="eyebrow">EVALUATION WORKSPACE</div><h2>评估中心</h2><p>读取项目中已保存的数据集和报告，不会在页面打开时触发模型调用。</p></div><span class="read-only-badge">只读目录</span></section>
  <section class="metric-note"><span class="notice-icon">i</span><div><strong>数据集来源保持分开</strong><p>开发集、Agent 路由集和已观察过的 OOS 回归集分别显示。OOS-v2 已参与调优与回归，不能称作盲测成绩。</p></div></section>
  <section class="content-card"><div class="section-heading"><div><h3>已保存的评估资产</h3><p>样本数和指标只从文件内容读取；样本数不等于质量得分。</p></div></div><div v-if="loading" class="state-card">读取本地评估资产…</div><div v-else-if="error" class="state-card state-error">{{error}}</div><div v-else-if="!catalog.length" class="empty-state">暂无已保存的评估资产。</div><div v-else class="artifact-list"><article v-for="item in catalog" :key="item.artifact" class="artifact-row"><div class="artifact-icon">{{item.kind==='report'?'▧':'▤'}}</div><div class="artifact-name"><strong>{{item.artifact.split('/').at(-1)}}</strong><small>{{groupLabel(item.artifact)}} · {{item.kind==='report'?'报告':'数据/结果'}}<template v-if="item.dataset_id"> · {{item.dataset_id}}</template><template v-if="item.top_k"> · Top-{{item.top_k}}</template></small><div v-if="item.metrics" class="metric-tags"><span v-for="(value,key) in item.metrics" :key="key">{{key}} · {{typeof value==='number' && value<=1 ? (value*100).toFixed(1)+'%' : value}}</span></div><div v-if="item.reported_metrics?.length" class="reported-metrics"><small v-for="line in item.reported_metrics" :key="line">{{line}}</small></div></div><div class="artifact-count">{{item.records ?? '—'}}<small>{{item.records===undefined?'条数未解析':'条样本'}}</small></div><div class="artifact-size">{{(item.bytes/1024).toFixed(1)}} KB</div><button class="text-button" :disabled="artifactLoading" @click="openArtifact(item)">查看</button></article></div></section>
  <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="detail-modal evaluation-modal"><button class="modal-close" @click="selected=null">关闭</button><div class="eyebrow">SAVED EVALUATION ARTIFACT</div><h3>{{selected.artifact}}</h3><div v-if="Array.isArray(selected.content)" class="case-list"><article v-for="(item,index) in selected.content" :key="item.case_id||index" class="case-card"><strong>{{item.case_id||`样本 ${index+1}`}} · {{item.category||item.intent||"记录"}}</strong><p>{{item.query||item.question||item.input||item.expected_answer||JSON.stringify(item).slice(0,500)}}</p><small v-if="item.required_evidence||item.relevant_document_ids">相关证据：{{(item.required_evidence||item.relevant_document_ids).join("、")}}</small></article></div><div v-else-if="selected.content?.records" class="case-list"><article v-for="item in selected.content.records" :key="item.case_id" class="case-card"><strong>{{item.case_id}} · {{item.category}}</strong><p><b>问题：</b>{{item.question}}</p><p><b>预期：</b>{{item.expected_answer}}</p><small>召回：{{(item.retrieved_document_ids||[]).join("、")}}</small></article></div><pre v-else class="policy-content">{{typeof selected.content==='string'?selected.content:JSON.stringify(selected.content,null,2)}}</pre></section></div>
  <section class="metric-note"><span class="notice-icon">!</span><div><strong>在线执行、版本对比和 Bad Case 筛选暂未接入</strong><p>不会用静态占位图冒充评估历史。当前没有持久化评估运行表。</p></div></section></div></template>
